import { defineStore } from 'pinia'
import { computed, ref, watchEffect } from 'vue'

import type { User as UserConfig } from '@/schemas/apiSchema'
import { api } from '@/scripts/api'

export interface User {
  id?: number
  userId: string
  username: string
}

export const useUserStore = defineStore('user', () => {
  /**
   * The user config. null if not loaded.
   */
  const userConfig = ref<UserConfig | null>(null)
  /**
   * The current user id. null if not logged in or in single user mode.
   */
  const currentUserId = ref<string | null>(null)
  /**
   * Whether the current user is an admin.
   */
  const isAdmin = ref(false)
  const isMultiUserServer = computed(
    () => userConfig.value && 'users' in userConfig.value
  )
  const needsLogin = computed(
    () => !currentUserId.value && isMultiUserServer.value
  )
  const users = computed<User[]>(() =>
    (userConfig.value?.users ?? []).map(({ id, userId, username }: any) => ({
      id,
      userId,
      username
    }))
  )
  const currentUser = computed<User | null>(
    () =>
      users.value.find((user) => user.userId === currentUserId.value) ?? null
  )
  const initialized = computed(() => userConfig.value !== null)

  let initializePromise: Promise<void> | null = null

  /**
   * Initialize the user store.
   */
  async function initialize() {
    initializePromise ??= (async () => {
      try {
        // Set api.user from localStorage before making API calls
        // so that fetchApi includes the Comfy-User header
        const storedUserId = localStorage['Comfy.userId']
        if (storedUserId) {
          api.user = storedUserId
        }
        userConfig.value = await api.getUserConfig()
        // If localStorage had no userId but the API returned user data
        // (e.g. authenticated via cookie), use the API-returned user
        if (!storedUserId && userConfig.value?.users?.length) {
          const apiUserId = userConfig.value.users[0].userId
          currentUserId.value = apiUserId
          api.user = apiUserId
          localStorage['Comfy.userId'] = apiUserId
          if (userConfig.value.users[0].username) {
            localStorage['Comfy.userName'] = userConfig.value.users[0].username
          }
        } else {
          currentUserId.value = storedUserId ?? null
        }
        // Extract isAdmin from API response
        if (userConfig.value?.users?.length) {
          isAdmin.value = !!(userConfig.value.users[0] as any).isAdmin
        }
      } catch (err) {
        initializePromise = null
        throw err
      }
    })()
    return initializePromise
  }

  /**
   * Reset the initialize promise so that initialize() can be called again.
   * This is needed after logout or when the user state needs to be refreshed.
   */
  function resetInitialize() {
    initializePromise = null
  }

  /**
   * Create a new user.
   *
   * @param username - The username.
   * @returns The new user.
   */
  async function createUser(username: string): Promise<User> {
    const resp = await api.createUser(username)
    const data = await resp.json()
    if (resp.status >= 300) {
      throw new Error(
        data.error ??
          'Error creating user: ' + resp.status + ' ' + resp.statusText
      )
    }
    return {
      userId: data,
      username
    }
  }

  /**
   * Login the current user.
   *
   * @param user - The user.
   */
  async function login({
    userId,
    username
  }: {
    userId: string
    username: string
  }) {
    currentUserId.value = userId
    localStorage['Comfy.userId'] = userId
    localStorage['Comfy.userName'] = username
  }

  watchEffect(() => {
    if (currentUserId.value) {
      api.user = currentUserId.value
    }
  })

  /**
   * Logout the current user.
   */
  async function logout() {
    delete localStorage['Comfy.userId']
    delete localStorage['Comfy.userName']
    currentUserId.value = null
    userConfig.value = null
    isAdmin.value = false
    api.user = null
    resetInitialize()
  }

  return {
    users,
    currentUser,
    isMultiUserServer,
    needsLogin,
    isAdmin,
    initialized,
    initialize,
    resetInitialize,
    createUser,
    login,
    logout
  }
})
